const body = $json.body || $json;
const { user_id, chat_id, text, username } = body;

return [{ json: {
  userId: String(user_id || 'unknown'),
  chatId: String(chat_id || 'unknown'),
  username: String(username || 'anonymous'),
  message: String(text || '').trim(),
  ip: $json.headers?.['x-forwarded-for'] || $json.ip || '0.0.0.0',
  timestamp: Date.now()
}}];

const bans = $json.value || $json.data?.value || [];
const input = $('Extract Request').item.json;

const banEntry = bans.find(b => b.userId === input.userId || b.chatId === input.chatId);

if (banEntry) {
  const banExpired = banEntry.expiresAt && Date.now() > banEntry.expiresAt;
  if (!banExpired) {
    return [{ json: {
      allowed: false,
      reason: banEntry.reason || 'Banned',
      userStatus: 'banned',
      banExpires: banEntry.expiresAt ? new Date(banEntry.expiresAt).toISOString() : 'permanent'
    }}];
  }
}

return [{ json: { allowed: true, userStatus: 'ok' } }];

const input = $('Extract Request').item.json;
let msg = input.message;

// === ATTACK PATTERNS ===
const attackPatterns = [
  // SQL Injection
  { pattern: /('|--|\bUNION\b|\bSELECT\b.*\bFROM\b|\bDROP\b|\bDELETE\b.*\bFROM\b|\bINSERT\b.*\bINTO\b|\bOR\s+1\s*=\s*1)/i, type: 'sql_injection' },
  // Shell injection
  { pattern: /([;|&`$]\s*\b(bash|sh|cmd|powershell|exec|system|eval|rm\s|wget|curl|cat\s|sudo|chmod|chown)\b)/i, type: 'shell_injection' },
  // JavaScript injection (XSS)
  { pattern: /(<script|<\?php|<\?|<%.*?%>|javascript:|onerror=|onclick=|onload=)/i, type: 'xss' },
  // Token leakage
  { pattern: /(bot_token|api_key|password|secret|private_key|token\s*[=:]\s*\d+:[a-zA-Z0-9_-]+)/i, type: 'token_leak' },
  // Path traversal
  { pattern: /(\.\.\/|\.\.\\|\.\.%2f|\.\.%5c)/i, type: 'path_traversal' },
  // Very long messages (DoS)
  { pattern: null, maxLength: 10000, type: 'dos_attempt' }
];

const threats = [];
for (const ap of attackPatterns) {
  if (ap.pattern && ap.pattern.test(msg)) {
    threats.push({ type: ap.type, severity: 'high' });
    msg = msg.replace(ap.pattern, '[REDACTED]');
  }
  if (ap.maxLength && msg.length > ap.maxLength) {
    threats.push({ type: ap.type, severity: 'medium' });
    msg = msg.substring(0, ap.maxLength);
  }
}

// Spam detection
const spamScore = (
  (/(.)\1{10,}/.test(msg) ? 3 : 0) +  // repeated chars
  (/[A-Z\s]{20,}/.test(msg) ? 2 : 0) +  // ALL CAPS
  ((msg.match(/\b(buy|click|free|win|urgent|limited|offer|act now|call now|subscribe|deal|exclusive|prize|congratulations|you are the|selected|winner|earn money|work from home|make money|sign up|join now)\b/gi) || []).length * 2)
);

return [{ json: {
  sanitizedMessage: msg,
  threats: threats,
  spamScore: spamScore,
  isThreat: threats.length > 0,
  isSpam: spamScore >= 5
}}];

const input = $('Extract Request').item.json;
const existing = $('Load Rate Limit Data').item.json.value || $('Load Rate Limit Data').item.json.data?.value || null;

const now = Date.now();
const WINDOW_MS = 60000; // 1 min
const MAX_REQUESTS = 30;

let rl = existing || { userId: input.userId, timestamps: [] };

// Clean old entries
rl.timestamps = rl.timestamps.filter(t => now - t < WINDOW_MS);
rl.timestamps.push(now);

rl.count = rl.timestamps.length;
rl.remaining = Math.max(0, MAX_REQUESTS - rl.count);
rl.resetAt = now + WINDOW_MS;

const rateLimited = rl.count > MAX_REQUESTS;

return [{ json: { ...$json, rateLimit: rl, rateLimited } }];

const banCheck = $('Check Ban Status').item.json;
const sanitize = $('Input Sanitizer').item.json;
const rl = $('Check Rate Limit').item.json;
const input = $('Extract Request').item.json;

let allowed = true;
let reason = '';

if (!banCheck.allowed) {
  allowed = false;
  reason = banCheck.reason;
} else if (rl.rateLimited) {
  allowed = false;
  reason = `Rate limited. Try again in ${Math.ceil((rl.rateLimit.resetAt - Date.now()) / 1000)}s`;
} else if (sanitize.isThreat) {
  allowed = false;
  reason = `Threat detected: ${sanitize.threats.map(t => t.type).join(', ')}`;
  // Auto-ban for high-severity threats
  if (sanitize.threats.some(t => t.severity === 'high')) {
    const bans = $('Load Ban List').item.json.value || $('Load Ban List').item.json.data?.value || [];
    bans.push({ userId: input.userId, reason, expiresAt: now + 86400000 * 7 });
    // Save updated bans
  }
} else if (sanitize.isSpam) {
  allowed = false;
  reason = 'Spam detected';
}

return [{ json: {
  allowed,
  reason,
  sanitizedMessage: sanitize.sanitizedMessage,
  threats: sanitize.threats,
  spamScore: sanitize.spamScore,
  userId: input.userId,
  chatId: input.chatId,
  username: input.username,
  rateLimitRemaining: rl.rateLimit.remaining
}}];

const decision = $('Decision Engine').item.json;
const log = {
  timestamp: new Date().toISOString(),
  userId: decision.userId,
  chatId: decision.chatId,
  username: decision.username,
  allowed: decision.allowed,
  reason: decision.reason || 'ok',
  threats: decision.threats || [],
  spamScore: decision.spamScore || 0
};

// Load existing audit log, append, save
// Keep last 1000 entries
return [{ json: { ...decision, auditEntry: log } }];
